theorem num_lm_semiconj_maps_fixedPoint {α β : Type*} {fa : α → α} {fb : β → β} {g : α → β}
    {x : α} (hx : IsFixedPt fa x) (h : Semiconj g fa fb) : IsFixedPt fb (g x) :=
  hx.map h

def rel_lorentz_gamma (v c : Float) : Float :=
  1 / Float.sqrt (1 - (v / c) * (v / c))

/-- Proper time dτ = dt/γ (P-LM-MC-030). -/

def rel_minkowski_interval_sq (c t x : Float) : Float :=
  (c * t) * (c * t) - x * x

/-- Schwarzschild time factor √(1 − r_s/r) (P-LM-MC-100). -/

def rel_schwarzschild_factor (rs r : Float) : Float :=
  Float.sqrt (1 - rs / r)

